@Test
	@PactVerification
	public void runTestBeer() {
		// OK
		assertEquals(this.controller.gimmeABeer(new Person("marcin", 25)), "THERE YOU GO");

		// NOT_OK
		assertEquals(this.controller.gimmeABeer(new Person("marcin", 10)), "GET LOST");
	}

